-- Newsletter DRAFTS generated by scripts/newsletter-drafts/build.mts.
-- Inserts as status 'draft' / stage 'early'; nothing here schedules or sends.
-- Skips any draft whose title already exists. Safe to re-run.

-- hey-zomi-share-the-dignity
insert into public.newsletters
  (title, subject, preheader, audience, blocks, status, stage)
select
  'Signal: Hey Zomi and Share the Dignity',
  'A signal worth sharing 🔴',
  'How a room full of Signal guests helped get [X] reusable menstrual discs to people who need them.',
  'subscribers',
  $nl$[{"id":"hey-zomi-share-the-dignity-01","type":"header","text":"A signal worth sharing.","size":"lg"},{"id":"hey-zomi-share-the-dignity-02","type":"image","src":"https://tedxnewy.com.au/images/newsletter/hey-zomi-reel-phone.jpg","alt":"Watch the Hey Zomi and TEDxNewy reel: Mika holding a Hey Zomi reusable menstrual disc","widthPct":80,"href":"https://www.instagram.com/p/DeYw-tFTHJf/"},{"id":"hey-zomi-share-the-dignity-03","type":"text","html":"<p>At Signal, our partner Hey Zomi gave every guest one of their reusable menstrual discs.</p><p>If it wasn't for you, you were invited to donate it instead. And so many of you did.</p><p>Together, we've donated <strong>[X] reusable menstrual discs</strong> to Share the Dignity, getting period care to people who need it most.</p><p>Thank you to everyone who passed one on.</p>"},{"id":"hey-zomi-share-the-dignity-04","type":"divider","style":"short","colour":"soft"},{"id":"hey-zomi-share-the-dignity-05","type":"header","text":"Two sisters, sending a signal from Newy","size":"md"},{"id":"hey-zomi-share-the-dignity-06","type":"image","src":"https://tedxnewy.com.au/images/newsletter/hey-zomi-sisters.jpg","alt":"Hey Zomi founders Mika and Zoe, smiling and holding Hey Zomi menstrual disc boxes","widthPct":100,"href":"https://www.heyzomi.com"},{"id":"hey-zomi-share-the-dignity-07","type":"text","html":"<p>Hey Zomi was started by sisters Mika and Zoe, right here in Newcastle, to make period care more comfortable, more sustainable and more accessible.</p><p>They already partner with Share the Dignity, and they brought that same generosity to Signal. We're proud they're from Newy, and we're proud of the signal they're putting out into the world.</p><p>Mika shared why they partnered with us in a short video and blog post.</p>"},{"id":"hey-zomi-share-the-dignity-08","type":"button","label":"Watch the reel","href":"https://www.instagram.com/p/DeYw-tFTHJf/","align":"center","theme":"ink","variant":"outline"},{"id":"hey-zomi-share-the-dignity-09","type":"button","label":"Read the blog post","href":"https://www.heyzomi.com/blogs/learn/a-signal-worth-sharing-why-hey-zomi-partnered-with-tedxnewy","align":"center","theme":"ink","variant":"outline"},{"id":"hey-zomi-share-the-dignity-10","type":"divider","style":"short","colour":"soft"},{"id":"hey-zomi-share-the-dignity-11","type":"header","text":"Curious to try one?","size":"md"},{"id":"hey-zomi-share-the-dignity-12","type":"image","src":"https://tedxnewy.com.au/images/newsletter/hey-zomi-woolworths.jpg","alt":"A Hey Zomi billboard reading 92% of us leak, the rest of us use Hey Zomi, available at Woolworths","widthPct":100,"href":"https://www.heyzomi.com"},{"id":"hey-zomi-share-the-dignity-13","type":"text","html":"<p>If Signal got you thinking about switching to reusable period care, now is a good time to look. Hey Zomi's sitewide Black Friday sale has <strong>30% off</strong> their menstrual discs and reusable period care.</p><p>You'll also find them at Woolworths.</p>"},{"id":"hey-zomi-share-the-dignity-14","type":"button","label":"Discover Hey Zomi","href":"https://www.heyzomi.com","align":"center","theme":"red","variant":"solid"},{"id":"hey-zomi-share-the-dignity-15","type":"text","html":"<p>Thank you, Mika and Zoe, and thank you to everyone who gave.</p><p>Will and the TEDxNewy team</p>"}]$nl$::jsonb,
  'draft',
  'early'
where not exists (
  select 1 from public.newsletters where title = 'Signal: Hey Zomi and Share the Dignity'
);
